<?php
require __DIR__.'/app/bootstrap.php';$u=require_user();require_commerce();$title='Checkout';$err=[];$cart=cart_data();$groups=checkout_groups($cart);$methods=[];
$postedMethods=$_SERVER['REQUEST_METHOD']==='POST' && is_array($_POST['method']??null)?$_POST['method']:[];
foreach($groups as $seller=>$group){$candidate=$postedMethods[$seller]??null;$methods[$seller]=is_string($candidate)?$candidate:($group['options']['pickup_enabled']?'pickup':'delivery');}
$name=$_SERVER['REQUEST_METHOD']==='POST'?val('customer_name'):$u['full_name'];$phone=$_SERVER['REQUEST_METHOD']==='POST'?val('customer_phone'):$u['phone'];$address=$_SERVER['REQUEST_METHOD']==='POST'?val('delivery_address'):($u['delivery_address']??'');$note=val('note');
if(post()){
 $token=val('quote_token');$requestKey=hash('sha256',$token);$prior=preg_match('/^[a-f0-9]{48}$/',$token)?one('SELECT id FROM order_batches WHERE request_key=? AND customer_id=?',[$requestKey,$u['id']]):null;
 if($prior)go('order-confirmation.php?batch='.$prior['id']);
 $quote=$_SESSION['checkout_quotes'][$token]??null;
 if(!$quote||$quote['expires']<time())$err[]='Your checkout has expired. Review the current totals and place your order again.';
 if(!$cart['items'])$err[]='Your cart is empty or its dishes are no longer available.';
 if(!text_valid($name,2,120))$err[]='Enter the recipient’s full name.';
 if(!preg_match('/^\+?[0-9 ()-]{8,25}$/',$phone)||strlen(preg_replace('/\D/','',$phone))<8)$err[]='Enter a valid contact phone number.';
 if(!text_valid($note,0,1000))$err[]='Keep your note under 1000 characters.';
 $needsAddress=false;
 foreach($groups as $seller=>$group){$method=$methods[$seller];if(!in_array($method,['pickup','delivery'])||!$group['options'][$method.'_enabled'])$err[]='Choose an available pickup or delivery option for '.$group['shop']['business_name'].'.';if($method==='delivery')$needsAddress=true;}
 if($needsAddress&&!text_valid($address,10,1500))$err[]='Enter a complete delivery address (10–1500 characters).';
 if(!$err){db()->beginTransaction();
  // Lock live product rows while validating prices and saving the order snapshot.
  $ids=array_column($cart['items'],'id');sort($ids);$marks=implode(',',array_fill(0,count($ids),'?'));
  q('SELECT id FROM menu_items WHERE id IN ('.$marks.') ORDER BY id'.(cfg('db_driver')==='mysql'?' FOR UPDATE':''),$ids)->fetchAll();
  foreach(array_keys($groups) as $seller){q('UPDATE users SET full_name=full_name WHERE id=?',[$seller]);q('SELECT seller_id FROM seller_fulfillment WHERE seller_id=?'.(cfg('db_driver')==='mysql'?' FOR UPDATE':''),[$seller])->fetchAll();}
  $cart=cart_data();$groups=checkout_groups($cart);
  if(!$groups||!hash_equals($quote['fingerprint'],checkout_fingerprint($groups))){db()->rollBack();$err[]='Your cart, dish availability or delivery prices changed. Review the updated total before placing your order.';}
  else{
   $batch=bin2hex(random_bytes(24));q('INSERT INTO order_batches (id,customer_id,request_key,created_at) VALUES (?,?,?,?)',[$batch,$u['id'],$requestKey,now()]);
   foreach($groups as $seller=>$group){$method=$methods[$seller];$fee=$method==='delivery'?(int)$group['options']['delivery_fee_paisa']:0;$shop=$group['shop'];$ref='CR-'.strtoupper(bin2hex(random_bytes(5)));
    q('INSERT INTO orders (reference,batch_id,customer_id,seller_id,shop_name,shop_address,shop_phone,fulfillment,subtotal_paisa,delivery_fee_paisa,total_paisa,status,customer_name,customer_phone,delivery_address,note,created_at,updated_at) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)',[$ref,$batch,$u['id'],$seller,$shop['business_name'],$shop['address'],$shop['business_phone'],$method,$group['subtotal'],$fee,$group['subtotal']+$fee,'placed',$name,$phone,$method==='delivery'?$address:'',$note,now(),now()]);$orderId=(int)db()->lastInsertId();
    foreach($group['items'] as $item)q('INSERT INTO order_items (order_id,product_id,product_key,name,quantity,unit_price_paisa,total_paisa) VALUES (?,?,?,?,?,?,?)',[$orderId,$item['id'],$item['id'],$item['name'],$item['quantity'],$item['price_paisa'],$item['line_total']]);
   }
   db()->commit();$_SESSION['cart']=[];unset($_SESSION['checkout_quotes'][$token]);go('order-confirmation.php?batch='.$batch);
  }
 }
}
$quoteToken=checkout_quote($groups);$subtotal=array_sum(array_column($groups,'subtotal'));$deliveryTotal=0;$needsAddress=false;
foreach($groups as $seller=>$group)if(($methods[$seller]??'pickup')==='delivery'){$deliveryTotal+=(int)$group['options']['delivery_fee_paisa'];$needsAddress=true;}
require ROOT.'/app/header.php'; ?>
<main class="page shell" id="main"><div class="page-heading"><span class="heading-kicker">A FEW FINAL DETAILS</span><h1>Checkout</h1><p>Choose pickup or delivery for each shop. Delivery charges are shown separately.</p></div><?php errors($err); ?><?php if(!$groups): ?><div class="panel empty"><p>Your cart is empty. Find something delicious first.</p><a class="pill primary" href="<?=e(url('index.php'))?>">Explore Food →</a></div><?php else: ?><form method="post" class="checkout-layout" id="checkout-form"><?=csrf()?><input type="hidden" name="quote_token" value="<?=e($quoteToken)?>"><div class="checkout-main">
<?php foreach($groups as $seller=>$group): $options=$group['options']; ?><section class="panel padded checkout-shop" data-shop="<?=$seller?>" data-subtotal="<?=$group['subtotal']?>"><h2><?=e($group['shop']['business_name'])?></h2><?php foreach($group['items'] as $item): ?><div class="checkout-item"><span><?=e($item['name'])?> × <?=$item['quantity']?></span><strong><?=money($item['line_total'])?></strong></div><?php endforeach ?><fieldset class="fulfillment-options"><legend>How would you like this order?</legend><label class="fulfillment-choice <?=!$options['pickup_enabled']?'unavailable':''?>"><input type="radio" name="method[<?=$seller?>]" value="pickup" data-fee="0" required <?=$methods[$seller]==='pickup'?'checked':''?> <?=$options['pickup_enabled']?'':'disabled'?>><span><strong>Self pickup</strong><small><?=$options['pickup_enabled']?'Collect from the shop · No delivery charge':'Pickup unavailable'?></small></span><b>Rs 0</b></label><label class="fulfillment-choice <?=!$options['delivery_enabled']?'unavailable':''?>"><input type="radio" name="method[<?=$seller?>]" value="delivery" data-fee="<?=$options['delivery_fee_paisa']?>" <?=$methods[$seller]==='delivery'?'checked':''?> <?=$options['delivery_enabled']?'':'disabled'?>><span><strong>Delivery</strong><small><?=$options['delivery_enabled']?'Delivered by the shop':'Delivery unavailable'?></small></span><b><?=$options['delivery_enabled']?money((int)$options['delivery_fee_paisa']):'—'?></b></label></fieldset><p class="pickup-location"><strong>Pickup location:</strong> <?=e($group['shop']['address'])?></p></section><?php endforeach ?>
<section class="panel padded"><h2>Contact details</h2><div class="form-grid"><?php field('customer_name','Recipient name','text','required maxlength="120" autocomplete="name"',$name);field('customer_phone','Contact phone','tel','required maxlength="25" autocomplete="tel"',$phone); ?></div><div id="delivery-address-section"><?php area('delivery_address','Delivery address (required for delivery)',$address,'maxlength="1500" autocomplete="street-address"'.($needsAddress?' required':'')); ?><p class="hint" data-address-hint><?=$needsAddress?'This address is used for the selected deliveries.':'No address is needed for pickup. Leave this blank if you are collecting every order.'?></p></div><?php area('note','Order note (optional)',$note,'maxlength="1000" placeholder="Anything the shop should know?"'); ?></section></div>
<aside class="panel padded checkout-summary"><h2>Your total</h2><div class="total-line"><span>Food subtotal</span><strong><?=money($subtotal)?></strong></div><div class="total-line"><span>Delivery charges</span><strong data-delivery-total><?=money($deliveryTotal)?></strong></div><div class="delivery-breakdown"><?php foreach($groups as $seller=>$group): ?><div><span><?=e($group['shop']['business_name'])?></span><b data-shop-fee="<?=$seller?>"><?=money(($methods[$seller]??'pickup')==='delivery'?(int)$group['options']['delivery_fee_paisa']:0)?></b></div><?php endforeach ?></div><div class="total-line grand-total"><span>Total</span><strong data-checkout-total><?=money($subtotal+$deliveryTotal)?></strong></div><p class="payment-note">Pay directly to each shop: on pickup or cash on delivery.</p><?php if(count($groups)>1): ?><p class="hint">Each shop receives a separate order.</p><?php endif ?><button class="pill primary wide" type="submit">Place Order →</button><a class="checkout-back" href="<?=e(url('cart.php'))?>">Edit cart</a></aside></form><?php endif ?></main><?php require ROOT.'/app/footer.php'; ?>
